import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, build, synth
root = tempfile.mkdtemp()
@synth.generator
def samples(ctx):
    features = torch.randn(4, generator=ctx.rng.torch)
    targets = torch.tensor([[1.0, 1.0]])
    return {"inputs": synth.Tensor(features), "targets": synth.Tensor(targets)}
dataset = synth.Spec("integral-regression", generator=samples, size=12, splits={"train": 1.0}, seed=7, root=root, monitor="none").run()
train = dataset.for_recipe("structured-objective", split="train")
class HeatmapPredictor(nn.Module):
    def __init__(self):
        super().__init__()
        self.network = build("mlp", "tiny", in_features=4, out_features=4)
    def forward(self, inputs):
        return {"heatmaps": self.network(inputs).reshape(inputs.shape[0], 1, 2, 2)}
trainer = Trainer(HeatmapPredictor(), train, recipe="structured-objective", recipe_config={"loss": "integral-regression", "bindings": {"logits_or_prediction": {"output": "heatmaps"}, "targets": {"batch": "targets"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
